221→// getMetadataTree returns the metadata branch tree, trying a treeless fetch
222→// first to ensure local data is up-to-date, then falling back to local,
223→// then full fetch, then remote tree directly.
224→func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
225→	// Always try treeless fetch first to ensure local branch is up-to-date
226→	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
227→		metadataTree, err := strategy.GetMetadataBranchTree(repo)
228→		if err == nil {
229→			return metadataTree, nil
230→		}
231→	}
232→
233→	// Try local (may have been set by a prior fetch or push)
234→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
235→	if err == nil {
236→		return metadataTree, nil
237→	}
238→
239→	// Fallback: full fetch from remote
240→	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
241→		metadataTree, err = strategy.GetMetadataBranchTree(repo)
242→		if err == nil {
243→			return metadataTree, nil
244→		}
245→	}
246→
247→	// Try remote tree directly
248→	remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
249→	if remoteErr != nil {
250→		return nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
251→	}
252→	return remoteTree, nil
253→}
