255→// ensureTranscriptBlobs checks which transcript blobs for a checkpoint are
256→// present in the local object store (via go-git) and fetches any missing
257→// ones from the remote (via git CLI).
258→// This enables the treeless-fetch optimization: tree objects are fetched first,
259→// then only the specific full.jsonl blobs needed for resume are downloaded.
260→func ensureTranscriptBlobs(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
261→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
262→	if err != nil {
263→		// If we can't get the tree, blobs can't be checked — caller will handle the error
264→		return nil //nolint:nilerr // Tree unavailable means no sparse fetch possible
265→	}
266→
267→	refs, err := checkpoint.CollectTranscriptBlobHashes(metadataTree, checkpointID)
268→	if err != nil {
269→		// Tree navigation failed — not fatal, ReadSessionContent will fail with a clear error
270→		return nil //nolint:nilerr // Best-effort blob prefetch
271→	}
