// clearGlobalHooksPath overrides any global core.hooksPath setting so that
// test repos use their default .git/hooks directory.
func clearGlobalHooksPath(t *testing.T, repoDir string) {
	t.Helper()
	cmd := exec.CommandContext(context.Background(), "git", "config", "--local", "--unset", "core.hooksPath")
	cmd.Dir = repoDir
	// Ignore exit code 5 (key not set) — only fail on real errors.
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok && exitErr.ExitCode() == 5 {
			return
		}
		t.Fatalf("failed to unset core.hooksPath: %v", err)
	}
}

